#!/usr/bin/env python3
"""Emit canary_bytes.inc for the oracle firmware (same rules as oracle_lib)."""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from oracle_lib import CANARY_LEN, PAGE, canary_expect  # noqa: E402


def main() -> int:
    lines = [
        "/* generated by gen_canary.py — do not edit */",
    ]
    for off in range(0, CANARY_LEN, PAGE):
        chunk = ", ".join(f"0x{canary_expect(off + i):02X}" for i in range(PAGE))
        comma = "," if off + PAGE < CANARY_LEN else ""
        lines.append(f"    {chunk}{comma}")
    Path("canary_bytes.inc").write_text("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
